"""
SUTRA Autonomous Flight Copilot Engine.
Continuously watches video perception telemetry, reasons about experiment progression,
detects missing actions or procedural errors, and autonomously guides the astronaut
hands-free via audio directives and HUD telemetry—without requiring any manual typing or chat.
"""

import logging
import os
import time
from dataclasses import dataclass, field
from typing import Optional

logger = logging.getLogger("sutra.copilot")


@dataclass
class CopilotDirective:
    """Autonomous guidance packet generated by the LLM / Cognitive Engine."""
    timestamp: float
    current_status: str
    missing_or_deviation: Optional[str] = None
    next_action_directive: str = ""
    spoken_announcement: str = ""
    alert_level: str = "INFO"  # 'INFO', 'WARNING', 'CRITICAL'


class AutonomousCopilotEngine:
    """
    Self-driving experiment guardian for Bharatiya Antariksh Station (BAS).
    Uses Groq LLM (or deterministic flight controller rules) to autonomously
    supervise experiment execution, detect deviations, and narrate instructions.
    """

    def __init__(self, api_key: Optional[str] = None, model: str = "llama-3.3-70b-versatile"):
        self.api_key = api_key or os.getenv("GROQ_API_KEY")
        self.model = model
        self._groq_client = None
        self._last_guidance_time = 0.0
        self._last_step_id = None
        self._last_deviation_hash = None
        self._guidance_cooldown_s = 6.0  # Avoid spamming voice announcements

        if self.api_key:
            try:
                from groq import Groq
                self._groq_client = Groq(api_key=self.api_key)
                logger.info(f"Autonomous Groq Copilot active with model: {self.model}")
            except Exception as e:
                logger.warning(f"Could not initialize Groq client: {e}")
                self._groq_client = None

    def evaluate_state_autonomously(
        self,
        experiment_context: dict,
        force_urgent: bool = False
    ) -> Optional[CopilotDirective]:
        """
        Evaluates current video state and autonomously emits guidance if:
        1. A step transition occurred (Started or Completed).
        2. A deviation was detected.
        3. Dwell time has elapsed without progress.
        """
        now = time.time()
        cur_step_id = experiment_context.get("current_step_id", "STEP_01")
        deviation = experiment_context.get("active_deviation")
        dev_hash = str(deviation) if deviation else None

        # Check triggers
        step_changed = (cur_step_id != self._last_step_id)
        deviation_triggered = (dev_hash is not None and dev_hash != self._last_deviation_hash)
        cooldown_elapsed = (now - self._last_guidance_time) >= self._guidance_cooldown_s

        if not (force_urgent or step_changed or deviation_triggered or cooldown_elapsed):
            return None

        self._last_guidance_time = now
        self._last_step_id = cur_step_id
        self._last_deviation_hash = dev_hash

        # Run LLM or Rule-Based Autonomous Analysis
        if self._groq_client is not None:
            directive = self._query_groq_copilot(experiment_context)
            if directive:
                return directive

        # Fallback to deterministic space flight controller
        return self._rule_based_copilot(experiment_context)

    def _query_groq_copilot(self, ctx: dict) -> Optional[CopilotDirective]:
        try:
            prompt = f"""You are the SUTRA Autonomous Flight Copilot inside a Bharatiya Antariksh Station (BAS) payload bay.
You are watching the astronaut work through the camera feed in real time. Do NOT act like a chatbot.
Generate a concise, authoritative flight directive for the astronaut.

CURRENT TELEMETRY SNAPSHOT:
- Protocol: {ctx.get('protocol_name', 'Biological Reagent Dispensation')}
- Current Step: {ctx.get('current_step_id')} - {ctx.get('current_step_name')}
- Step Status: {ctx.get('step_status')}
- Active Deviation: {ctx.get('active_deviation')}
- Observed Objects: {ctx.get('detected_objects', [])}
- Active Physical Action: {ctx.get('active_action', 'None')}

Output strictly valid JSON with these 4 keys (no markdown code blocks, just raw JSON):
{{
  "current_status": "Brief explanation of what is currently observed",
  "missing_or_deviation": "What is missing or skipped, or null if normal",
  "next_action_directive": "Exact physical action the astronaut must perform next",
  "spoken_announcement": "One clear, natural sentence to speak aloud to the astronaut (English or Hinglish)",
  "alert_level": "INFO or WARNING or CRITICAL"
}}
"""
            chat = self._groq_client.chat.completions.create(
                messages=[
                    {"role": "system", "content": "You are SUTRA, an autonomous mission copilot. Return only raw JSON."},
                    {"role": "user", "content": prompt}
                ],
                model=self.model,
                temperature=0.2,
                max_tokens=250,
                response_format={"type": "json_object"}
            )
            raw = chat.choices[0].message.content.strip()
            import json
            data = json.loads(raw)
            return CopilotDirective(
                timestamp=time.time(),
                current_status=data.get("current_status", "Monitoring experiment"),
                missing_or_deviation=data.get("missing_or_deviation"),
                next_action_directive=data.get("next_action_directive", "Continue protocol sequence"),
                spoken_announcement=data.get("spoken_announcement", "Monitoring active step."),
                alert_level=data.get("alert_level", "INFO")
            )
        except Exception as e:
            logger.error(f"Autonomous Groq reasoning error: {e}")
            return None

    def _rule_based_copilot(self, ctx: dict) -> CopilotDirective:
        """Deterministic flight guidance rules for the 5-step assay."""
        step_id = ctx.get("current_step_id", "STEP_01")
        step_name = ctx.get("current_step_name", "Workspace Inspection & Sanitization")
        dev = ctx.get("active_deviation")

        if dev:
            desc = dev.get("description", "A procedural deviation was detected.")
            missing = dev.get("uncompleted_step", "preceding step")
            attempted = dev.get("attempted_step", "next action")
            return CopilotDirective(
                timestamp=time.time(),
                current_status=f"Procedural violation detected: {desc}",
                missing_or_deviation=f"Step '{missing}' was skipped or not confirmed before '{attempted}'.",
                next_action_directive=f"Stop current action. Return to '{missing}' to maintain experiment validity.",
                spoken_announcement=f"Caution! Procedural deviation detected. Please complete {missing} first.",
                alert_level="CRITICAL"
            )

        if step_id == "STEP_01":
            return CopilotDirective(
                timestamp=time.time(),
                current_status="Step 1 active: Inspecting and clearing payload workspace.",
                missing_or_deviation=None,
                next_action_directive="Bring hands into workspace to confirm sterile enclosure.",
                spoken_announcement="Step 1 active: Please inspect and confirm payload workspace.",
                alert_level="INFO"
            )
        elif step_id == "STEP_02":
            return CopilotDirective(
                timestamp=time.time(),
                current_status="Step 2 active: Sample container unsealing.",
                missing_or_deviation="Sample vial seal intact; cap must be removed before liquid handling.",
                next_action_directive="Grasp target sample vial and remove the seal cap.",
                spoken_announcement="Step 2: Unseal the target sample container.",
                alert_level="INFO"
            )
        elif step_id == "STEP_03":
            return CopilotDirective(
                timestamp=time.time(),
                current_status="Step 3 active: Reagent aspiration.",
                missing_or_deviation="Pipette not yet charged with reagent buffer.",
                next_action_directive="Grasp micropipette, insert tip into reagent vial, and draw required volume.",
                spoken_announcement="Step 3: Grasp micropipette and aspirate reagent.",
                alert_level="INFO"
            )
        elif step_id == "STEP_04":
            return CopilotDirective(
                timestamp=time.time(),
                current_status="Step 4 active: Liquid dispensation.",
                missing_or_deviation=None,
                next_action_directive="Align pipette tip into target container and discharge liquid reagent.",
                spoken_announcement="Step 4: Dispense liquid into target container.",
                alert_level="INFO"
            )
        elif step_id == "STEP_05":
            return CopilotDirective(
                timestamp=time.time(),
                current_status="Step 5 active: Container sealing.",
                missing_or_deviation="Sample vial is still open; must be sealed before completion.",
                next_action_directive="Reseal target container cap and return pipette to rack cradle.",
                spoken_announcement="Final step: Reseal container and stow tools.",
                alert_level="INFO"
            )
        else:
            return CopilotDirective(
                timestamp=time.time(),
                current_status="Protocol Completed: All 5 steps verified.",
                missing_or_deviation=None,
                next_action_directive="Experiment finalized. Telemetry ready for ground downlink.",
                spoken_announcement="Experiment completed successfully. All steps verified.",
                alert_level="INFO"
            )

